// Planetary Computer - cognition benchmark simulation (Mark 1 demonstration run)
// Run with: node demo.js
'use strict';
var bench=[320,710,960], energy=[48,6,0.7];
var tasks=["reasoning","planning","creativity","alignment probes","tool use"];
console.log("Planetary Computer - benchmark by generation");
console.log("==================================================");
for(var m=0;m<3;m++){
  console.log("Mark "+(m+1)+": composite "+bench[m]+"/1000, "+energy[m]+" kJ/task");
  var line=" ";
  for(var t=0;t<tasks.length;t++){ line+=tasks[t]+"="+(bench[m]*(0.9+0.04*t)).toFixed(0)+" "; }
  console.log(line);
}
console.log("Efficiency gain Mark I -> Mark III: "+(energy[0]/energy[2]).toFixed(1)+"x less energy per task.");

